    flex-wrap: wrap;
    gap: 4px;
    flex: 1;
    justify-content: center;
  }

  .rail-item span {
    display: none;
  }

  .rail-item {
    padding: 8px;
    min-width: 40px;
    justify-content: center;
  }

  .rail-footer {
    display: none;
  }

  .topbar {
    grid-row: 1;
    grid-column: 1;
  }

  .topbar-hamburger {
    display: flex;
  }

  .topbar-title {
    display: none;
  }

  .topbar-center {
