  }

  .panel-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }

  .panel-controls {
    width: 100%;
    flex-wrap: wrap;
  }

  .filter-group {
    flex: 1;
    min-width: 140px;
  }

  .filter-group select {
