@media (max-width: 390px) {
  html {
    font-size: 12px;
  }

  .topbar {
    padding: 0 12px;
  }

  .main {
    padding: 10px;
  }

  .metric {
    padding: 12px;
  }

  .metric-value {
    font-size: 22px;
  }

  .throughput {
    padding: 12px;
  }

  .chart-wrapper {
    height: 160px;
  }

