        { time: '14:25', event: 'Root cause identified', detail: 'Connection pool maxed at 200, leak in retry logic v2.14.3' },
        { time: '14:28', event: 'Mitigation deployed', detail: 'Hotfix rolled back retry logic, pool recovering' },
